node /org/vibeos/Agent {
  interface org.freedesktop.DBus.Introspectable {
    methods:
      Introspect(out s data);
    signals:
    properties:
  };
  interface org.freedesktop.DBus.Peer {
    methods:
      GetMachineId(out s machine_uuid);
      Ping();
    signals:
    properties:
  };
  interface org.freedesktop.DBus.Properties {
    methods:
      Get(in  s interface_name,
          in  s property_name,
          out v value);
      Set(in  s interface_name,
          in  s property_name,
          in  v value);
      GetAll(in  s interface_name,
             out a{sv} props);
    signals:
      PropertiesChanged(s interface_name,
                        a{sv} changed_properties,
                        as invalidated_properties);
    properties:
  };
  interface org.freedesktop.DBus.ObjectManager {
    methods:
      GetManagedObjects(out a{oa{sa{sv}}} objpath_interfaces_and_properties);
    signals:
      InterfacesAdded(o object_path,
                      a{sa{sv}} interfaces_and_properties);
      InterfacesRemoved(o object_path,
                        as interfaces);
    properties:
  };
  interface org.vibeos.Agent {
    methods:
      ApproveReview(in  s review_id,
                    out s arg_1);
      AppsList(out s arg_0);
      AuditTail(in  i count,
                out s arg_1);
      Capabilities(out s arg_0);
      Command(in  s text,
              out s arg_1);
      CommandRequest(in  s payload_json,
                     out s arg_1);
      PendingReviews(out s arg_0);
      RejectReview(in  s review_id,
                   out s arg_1);
      Status(out s arg_0);
      TaskControl(in  s payload_json,
                  out s arg_1);
      TaskShow(in  s task_id,
               out s arg_1);
      TasksList(in  s payload_json,
                out s arg_1);
      WindowsList(out s arg_0);
    signals:
    properties:
  };
};

